<template><view class="page"><view class="card profile row"><image src="/static/dengkemiao.png" mode="aspectFit"/><view><view class="name">登科喵同学</view><view class="muted">坚持就是胜利！</view></view><text class="chevron">›</text></view><view class="card menus"><view class="menu" @click="tab('plan')"><view class="row"><text class="icon green">🎓</text><text>我的考试</text></view><text class="chevron">›</text></view><view class="menu" @click="tab('record')"><view class="row"><text class="icon blue">▥</text><text>学习记录</text></view><text class="chevron">›</text></view><view class="menu" @click="go('/pages/payment/index')"><view class="row"><text class="icon orange">♛</text><text>完整备考方案</text></view><text class="chevron">›</text></view><view class="menu" @click="privacy"><view class="row"><text class="icon grey">⚙</text><text>设置与隐私</text></view><text class="chevron">›</text></view><view class="menu" @click="about"><view class="row"><text class="icon blue">ⓘ</text><text>关于我们</text></view><text class="chevron">›</text></view></view><view class="card stats"><view><view class="number">{{count}}</view><text>备考计划</text></view><view><view class="number">{{streak}}</view><text>连续打卡</text></view><view><view class="number">{{completed}}</view><text>完成任务</text></view></view><view v-if="error" class="error">{{error}}</view><view v-if="localMode" class="notice">本地体验：计划保存在当前设备，清除缓存会删除数据。</view><view class="slogan">每一份努力，都会有回报。</view><view class="muted version">登科喵备考计划 · V1.0 开发预览</view></view></template>
<script setup>
import {ref} from 'vue';import {onShow} from '@dcloudio/uni-app';import {api,localMode,selected} from '../../api'
const count=ref(0),streak=ref(0),completed=ref(0),error=ref('')
onShow(async()=>{error.value='';try{const ps=await api.plans();count.value=ps.length;completed.value=ps.reduce((a,p)=>a+p.completedTasks,0);const p=ps.find(p=>p.id===selected())||ps[0];streak.value=p?(await api.records(p.id)).streak:0}catch(e){error.value=e.message}})
function tab(name){uni.switchTab({url:'/pages/'+name+'/index'})}function go(url){uni.navigateTo({url})}function privacy(){uni.showModal({title:'隐私与数据说明',content:localMode?'本地模式的计划与打卡数据保存在当前设备，清除缓存会删除数据。':'云端模式保存备考计划和学习记录，使用微信登录标识同步数据。正式上线前将提供完整隐私政策及数据删除入口。',showCancel:false})}function about(){uni.showModal({title:'登科喵备考计划',content:'科学规划 · 高效备考 · 一起上岸！\n计划由考试模板和规则引擎生成，请结合实际考试大纲安排具体学习内容。',showCancel:false})}
</script>
<style scoped>.profile{margin-top:10rpx;padding:26rpx 24rpx;justify-content:flex-start;gap:20rpx}.profile image{width:105rpx;height:105rpx;background:#EFF9F1;border-radius:50%}.name{font-size:32rpx;font-weight:750}.profile .muted{font-size:23rpx}.profile .chevron{margin-left:auto}.chevron{color:#8C9D94;font-size:36rpx}.menus{padding:0 24rpx}.menu{display:flex;align-items:center;justify-content:space-between;border-bottom:1rpx solid #EFF3F0;padding:23rpx 0;font-size:28rpx}.menu:last-child{border:0}.menu .row{gap:18rpx}.icon{display:block;width:42rpx;text-align:center;font-size:34rpx}.green{color:#12AF83}.blue{color:#5C8DFF}.orange{color:#FFB338}.grey{color:#8B9D97}.stats{display:flex;justify-content:space-around;text-align:center;padding:24rpx 12rpx}.stats text{font-size:22rpx;color:#899B91}.number{font-size:38rpx;font-weight:800;color:#194C36}.slogan{text-align:center;color:#2B8D66;font-size:25rpx;margin-top:35rpx}.version{text-align:center;font-size:20rpx;margin-top:14rpx}</style>
